def calculate_discount(total_amount: float, is_member: bool) -> float:
    if total_amount <= 0:
        return 0.0
    if is_member:
        rate = 0.8 if total_amount >= 200 else 0.9
    else:
        rate = 0.9 if total_amount >= 300 else 1.0
    return round(total_amount * rate, 2)

