def clean_and_split_name(full_name: str) -> tuple:
    """清洗全角空格并拆分中英文姓与名"""
    stripped = full_name.strip().replace("　", " ")
    parts = stripped.split()
    if len(parts) >= 2:
        return parts[0], " ".join(parts[1:])
    return full_name, ""

