exercises.answer:
def weighted_average(scores: list, weights: list = None) -> float:
    if not scores:
        return 0.0
    if weights is None:
        return round(sum(scores) / len(scores), 2)
    total_w = sum(weights)
    weighted_sum = sum(s * w for s, w in zip(scores, weights))
    return round(weighted_sum / total_w, 2)

