import csv
import io

def sum_csv_paid_orders(csv_text: str) -> float:
    if not csv_text.strip():
        return 0.0
    stream = io.StringIO(csv_text.strip())
    reader = csv.DictReader(stream)
    total = 0.0
    for row in reader:
        if row.get('status') == 'PAID':
            total += float(row.get('amount', 0))
    return round(total, 2)

import re

def extract_order_ids(log_text: str) -> list:
    if not log_text:
        return []
    return re.findall(r'ORD-\d{5}', log_text)

import numpy as np

def center_rows(mat: list) -> list:
    if not mat:
        return []
    arr = np.array(mat, dtype=float)
    row_means = arr.mean(axis=1, keepdims=True)
    centered = arr - row_means
    return np.round(centered, 2).tolist()

import pandas as pd

def filter_and_aggregate_orders(orders_df: pd.DataFrame) -> pd.DataFrame:
    if orders_df.empty:
        return pd.DataFrame(columns=['city', 'total_gmv', 'order_count'])
    # 复合筛选
    valid = orders_df[(orders_df['status'] == 'COMPLETED') & (orders_df['amount'] >= 100.0)]
    # 分组聚合
    res = valid.groupby('city').agg(
        total_gmv=('amount', 'sum'),
        order_count=('order_id', 'count')
    ).reset_index()
    res['total_gmv'] = res['total_gmv'].round(2)
    return res
